-- Apply transactionally once through the versioned updater. No document/snapshot/counter mutations.
CREATE TABLE IF NOT EXISTS "ProductCategory" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"name" varchar(80) NOT NULL,"normalizedKey" varchar(80) NOT NULL UNIQUE,"active" boolean NOT NULL DEFAULT true,"revision" integer NOT NULL DEFAULT 1 CHECK ("revision">0));
CREATE TABLE IF NOT EXISTS "ProductUnit" ("code" varchar(3) PRIMARY KEY,"description" varchar(120) NOT NULL,"active" boolean NOT NULL DEFAULT true,"revision" integer NOT NULL DEFAULT 1 CHECK ("revision">0));
ALTER TABLE "ProductCategory" ALTER COLUMN "id" SET DEFAULT gen_random_uuid();
-- Explicit Spanish case mapping also works on an existing C-locale Windows cluster.
CREATE OR REPLACE FUNCTION catalog_normalize(value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT translate(lower(regexp_replace(btrim(value),'[[:space:]]+',' ','g')),'ÁÉÍÓÚÜÑ','áéíóúüñ') $$;
CREATE OR REPLACE FUNCTION catalog_category_key() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW."name"=regexp_replace(btrim(NEW."name"),'[[:space:]]+',' ','g'); NEW."normalizedKey"=catalog_normalize(NEW."name"); IF length(NEW."name")=0 THEN RAISE EXCEPTION 'category name required'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS category_canonical ON "ProductCategory";
CREATE TRIGGER category_canonical BEFORE INSERT OR UPDATE ON "ProductCategory" FOR EACH ROW EXECUTE FUNCTION catalog_category_key();
INSERT INTO "ProductCategory" ("name","normalizedKey") SELECT min(regexp_replace(btrim("category"),'[[:space:]]+',' ','g')),catalog_normalize("category") FROM "FuelProduct" GROUP BY catalog_normalize("category") ON CONFLICT DO NOTHING;
INSERT INTO "ProductUnit" ("code","description") VALUES ('GLL','Galón'),('LTR','Litro'),('NIU','Unidad'),('KGM','Kilogramo'),('M3','Metro cúbico'),('HUR','Hora'),('ZZ','Servicio') ON CONFLICT DO NOTHING;
-- Unknown historical units remain readable, inactive until a supported profile/catalog is implemented.
INSERT INTO "ProductUnit" ("code","description","active") SELECT DISTINCT "unitCode",'Unidad histórica pendiente de homologación',false FROM "FuelProduct" ON CONFLICT DO NOTHING;
ALTER TABLE "FuelProduct" ADD COLUMN IF NOT EXISTS "categoryId" uuid REFERENCES "ProductCategory"("id") ON DELETE RESTRICT;
UPDATE "FuelProduct" p SET "categoryId"=c."id" FROM "ProductCategory" c WHERE c."normalizedKey"=catalog_normalize(p."category");
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='"FuelProduct"'::regclass AND contype='f' AND confrelid='"ProductUnit"'::regclass) THEN ALTER TABLE "FuelProduct" ADD CONSTRAINT product_unit_fk FOREIGN KEY ("unitCode") REFERENCES "ProductUnit"("code") ON DELETE RESTRICT ON UPDATE RESTRICT; END IF; END $$;
CREATE TABLE IF NOT EXISTS "BillingTaxPolicy" ("scopeKey" text PRIMARY KEY,"companyId" integer NOT NULL REFERENCES "CompanySettings"("id") ON DELETE RESTRICT,"branchId" uuid REFERENCES "Branch"("id") ON DELETE RESTRICT,"revision" integer NOT NULL CHECK ("revision">0),"overridden" boolean NOT NULL,"policy" jsonb NOT NULL,"updatedAt" timestamptz NOT NULL DEFAULT now(), CHECK ("scopeKey"=CASE WHEN "branchId" IS NULL THEN 'company:'||"companyId"::text ELSE 'branch:'||"branchId"::text END));
CREATE TABLE IF NOT EXISTS "BillingProductTax" ("scopeKey" text NOT NULL,"productId" uuid NOT NULL REFERENCES "FuelProduct"("id") ON DELETE RESTRICT,"companyId" integer NOT NULL REFERENCES "CompanySettings"("id"),"branchId" uuid REFERENCES "Branch"("id"),"revision" integer NOT NULL CHECK ("revision">0),"overridden" boolean NOT NULL,"treatment" varchar(2) NOT NULL CHECK ("treatment" IN ('10','20','30')),PRIMARY KEY ("scopeKey","productId"),CHECK ("scopeKey"=CASE WHEN "branchId" IS NULL THEN 'company:'||"companyId"::text ELSE 'branch:'||"branchId"::text END));
